import { Device } from '..';
import { DeviceInfo } from '../device-info';
import { Browser } from './browser';
import { OperatingSystem } from './operating-system';
import { OS_BROWSER_CODES } from './type-code-constants';

export function createDeviceTypeCode(device: Device) {
    try {
        const prefix = getDeviceTypePrefix(device);

        if (prefix === OS_BROWSER_CODES.UNKNOWN || prefix === OS_BROWSER_CODES.DESKTOP.UNKNOWN) {
            return `${prefix}`;
        } else if (prefix === null || prefix === undefined) {
            return OS_BROWSER_CODES.UNKNOWN;
        }
        
        const typeCode = `${prefix}${device.info.operatingSystem.version.major}`.substring(0, 9);

        if (isNaN(Number(typeCode))) {
            return OS_BROWSER_CODES.UNKNOWN;
        }

        return typeCode;
    } catch (e) {
        return OS_BROWSER_CODES.UNKNOWN;
    }
}

function getBrowserTypeCodeForOS(browser: Browser, browserCodes: { [browser: string]: string }) {
    if (browser.is('Chrome')) {
        return browserCodes.CHROME;
    }

    if (browser.is('Firefox')) {
        return browserCodes.FIREFOX;
    }

    if (browser.is('IE')) {
        return browserCodes.IE;
    }

    if (browser.is('Edge')) {
        return browserCodes.EDGE;
    }

    if (browser.is('Safari')) {
        return browserCodes.SAFARI;
    }

    return browserCodes.OTHER;
}

function getOSCodeForPlatform(operatingSystem: OperatingSystem, operatingSystemCodes: { [os: string]: string }) {
    if (operatingSystem.is('Android')) {
        return operatingSystemCodes.ANDROID;
    }

    if (operatingSystem.is('iOS')) {
        return operatingSystemCodes.IOS;
    }

    if (operatingSystem.is('Windows Phone')) {
        return operatingSystemCodes.WINDOWS_PHONE;
    }

    if (operatingSystem.is('BlackBerry')) {
        return operatingSystemCodes.BLACKBERRY;
    }

    return operatingSystemCodes.OTHER;
}

function getDesktopTypeCodePrefix(deviceInfo: DeviceInfo) {
    if (deviceInfo.operatingSystem.is('Mac OS')) {
        return getBrowserTypeCodeForOS(deviceInfo.browser, OS_BROWSER_CODES.DESKTOP.MAC_OS);
    }

    if (deviceInfo.operatingSystem.is('Windows')) {
        return getBrowserTypeCodeForOS(deviceInfo.browser, OS_BROWSER_CODES.DESKTOP.WINDOWS);
    }

    return OS_BROWSER_CODES.DESKTOP.UNKNOWN;
}

function getAppTypeCodePrefix(device: Device) {
    if (device.type.isTablet) {
        return getOSCodeForPlatform(device.info.operatingSystem, OS_BROWSER_CODES.APP.TABLET);
    }

    return getOSCodeForPlatform(device.info.operatingSystem, OS_BROWSER_CODES.APP.MOBILE);
}

function getDeviceTypePrefix(device: Device) {
    if (device.type.isDesktop) {
        return getDesktopTypeCodePrefix(device.info);
    }

    if (device.type.isApp) {
        return getAppTypeCodePrefix(device);
    }

    return getOSCodeForPlatform(device.info.operatingSystem, OS_BROWSER_CODES.DEVICE);
}